// Rebuilds runner-bundle.ts: `bun app/TinkerBelle/build-runner.ts`. Run it after upgrading @stacksjs/tinker.
import { join } from 'node:path'
import { buildRunnerBundle, runnerInputs } from './remote'

const code = await buildRunnerBundle()
const file = [
  '// Generated by build-runner.ts. Do not edit: run `bun app/TinkerBelle/build-runner.ts`.',
  '/* eslint-disable */',
  `export const RUNNER_INPUTS = ${JSON.stringify(await runnerInputs())}`,
  `export const RUNNER_BUNDLE = ${JSON.stringify(code)}`,
  '',
].join('\n')
await Bun.write(join(import.meta.dir, 'runner-bundle.ts'), file)
console.log(`runner-bundle.ts: ${code.length} bytes`)
